//! Opcode parity audit: Chorizite.ACProtocol → holtburger-protocol.
//!
//! This test loads `external/holtburger/apps/holtburger-web/data/chorizite/
//! chorizite-acprotocol-opcodes.json` (generated by the WB.Terminal
//! `chorizite-dump-opcodes` command) and compares the three Rust opcode enums
//! in `crate::opcodes` against the upstream Chorizite.ACProtocol enums on
//! (value → categorization) for every variant.
//!
//! Mapping (ACProtocol → Rust):
//!   - `C2SMessageType` ∪ `S2CMessageType`     →  `GameOpcode`
//!   - `GameActionType`                        →  `GameActionOpcode`
//!   - `GameEventType`                         →  `GameEventOpcode`
//!
//! Names are NOT expected to match between the two sources — Chorizite uses
//! `Category_VerbNoun` (e.g. `Combat_TargetedMeleeAttack`) while
//! holtburger-protocol uses bare PascalCase (e.g. `TargetedMeleeAttack`). The
//! test asserts on numeric values + which enum they live in, ignoring names.
//!
//! There are two tests:
//!
//! * `opcode_parity_categorization_gate` — the CI gate, always on. Fails if
//!   any opcode in Rust sits in a DIFFERENT enum than its Chorizite peer (a
//!   categorization mismatch), or if any opcode value in Rust does not match
//!   the value Chorizite has for the same name (a value mismatch). A small
//!   allowlist documents cases where retail (acclient.c / ACE-Server) confirms
//!   that Rust is right and Chorizite is wrong.
//!
//! * `opcode_parity_aspirational_stubs` (`#[ignore]`) — the audit report.
//!   Lists every opcode in Chorizite that is missing from Rust. Currently the
//!   Rust enums are a curated subset of the retail protocol (commented stubs
//!   in `opcodes.rs`); un-ignore this test once all S2C/GameEvent opcodes are
//!   wired up. Run with `cargo test ... -- --ignored`.
//!
//! The test deliberately does NOT depend on `serde_json`. The JSON shape is
//! tightly constrained (no nesting beyond two levels, no escapes in keys or
//! string values), so a hand-rolled tokenizer is sufficient and avoids
//! mutating the crate's Cargo.toml dev-dependencies.

use std::collections::BTreeMap;
use std::path::PathBuf;

use holtburger_protocol::opcodes::{GameActionOpcode, GameEventOpcode, GameOpcode};

/// Path to the generated JSON, relative to the crate manifest.
const JSON_REL_PATH: &str = "../../apps/holtburger-web/data/chorizite/chorizite-acprotocol-opcodes.json";

/// One enum slice of the dump: { hex_string → ACProtocol_name }.
type OpcodeMap = BTreeMap<u32, String>;

fn load_json() -> BTreeMap<String, OpcodeMap> {
    let mut path = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    path.push(JSON_REL_PATH);
    let src = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "Failed to read {} ({}). Regenerate via:\n  cd WorldBuilder.Terminal && \\\n    echo '{{\"command\":\"chorizite-dump-opcodes\"}}' | dotnet run --no-build -- --stdin\n",
            path.display(),
            e
        )
    });
    parse_opcode_json(&src)
}

/// Minimal hand-rolled parser tailored to the canonical shape emitted by the
/// `chorizite-dump-opcodes` command. It walks the file looking for nested
/// `"EnumName": { "0xHEX": "VariantName", ... }` blocks under the top-level
/// `"enums"` key. Anything outside that — `generatedBy`, `vendoredHead`,
/// `source` — is ignored. The output preserves the discovered order via the
/// internal BTreeMap ordering on the numeric opcode key.
fn parse_opcode_json(src: &str) -> BTreeMap<String, OpcodeMap> {
    // Locate the "enums": { … } block. We scan for the literal `"enums"`
    // key, then walk forward to the matching closing brace, counting depth.
    let enums_idx = src
        .find("\"enums\"")
        .expect("JSON missing top-level \"enums\" key — re-generate the dump");
    let after = &src[enums_idx..];
    let open_idx = enums_idx
        + after
            .find('{')
            .expect("JSON missing { after \"enums\"");
    let mut depth = 0i32;
    let mut end_idx = open_idx;
    for (i, ch) in src[open_idx..].char_indices() {
        match ch {
            '{' => depth += 1,
            '}' => {
                depth -= 1;
                if depth == 0 {
                    end_idx = open_idx + i + 1;
                    break;
                }
            }
            _ => {}
        }
    }
    assert!(depth == 0, "JSON \"enums\" block did not close cleanly");
    let body = &src[open_idx + 1..end_idx - 1]; // strip outer braces

    // Walk inner blocks: each is `"EnumName": { ... },` with the inner block
    // containing `"0xHEX": "Name",` entries.
    let mut out = BTreeMap::new();
    let mut cursor = 0usize;
    while let Some(name_start_rel) = body[cursor..].find('"') {
        let name_start = cursor + name_start_rel + 1;
        let name_end = name_start
            + body[name_start..]
                .find('"')
                .expect("malformed enum name in JSON");
        let enum_name = body[name_start..name_end].to_string();

        // Move past `":` and find the opening `{`.
        let block_open = name_end
            + body[name_end..]
                .find('{')
                .expect("malformed enum body in JSON");
        let mut block_depth = 0i32;
        let mut block_end = block_open;
        for (i, ch) in body[block_open..].char_indices() {
            match ch {
                '{' => block_depth += 1,
                '}' => {
                    block_depth -= 1;
                    if block_depth == 0 {
                        block_end = block_open + i + 1;
                        break;
                    }
                }
                _ => {}
            }
        }
        let inner = &body[block_open + 1..block_end - 1];

        // Parse each `"0xHEX": "Name"` pair.
        let mut members = OpcodeMap::new();
        let mut p = 0usize;
        while let Some(k_open_rel) = inner[p..].find('"') {
            let k_open = p + k_open_rel + 1;
            let k_close = k_open + inner[k_open..].find('"').expect("malformed key");
            let key = &inner[k_open..k_close];
            // Advance past `":`
            let after_colon = k_close
                + inner[k_close..]
                    .find(':')
                    .expect("malformed pair (no colon)")
                + 1;
            let v_open_rel = inner[after_colon..]
                .find('"')
                .expect("malformed pair (no value open quote)");
            let v_open = after_colon + v_open_rel + 1;
            let v_close = v_open + inner[v_open..].find('"').expect("malformed value");
            let value = &inner[v_open..v_close];

            assert!(
                key.starts_with("0x") || key.starts_with("0X"),
                "expected hex string key, got {key:?}"
            );
            let opcode = u32::from_str_radix(&key[2..], 16)
                .unwrap_or_else(|e| panic!("could not parse hex key {key:?}: {e}"));
            members.insert(opcode, value.to_string());

            p = v_close + 1;
        }

        out.insert(enum_name, members);
        cursor = block_end;
    }

    out
}

/// Enumerate every variant of a Rust opcode enum, returning a
/// `BTreeMap<u32, String>` of (value → Debug-formatted variant name).
///
/// `strum_macros::FromRepr` generates an inherent `from_repr` method on the
/// enum but NOT a generic `FromRepr` trait. Rather than introduce a custom
/// trait (which would force the production `opcodes.rs` to implement it) we
/// brute-force scan the relevant u32 range — fast enough since the upper
/// bound is < 0x10000 for these protocol opcodes.
///
/// Why a macro instead of a `fn<T>`: `from_repr` lives in inherent impl
/// space, so we can't write `T::from_repr(v)` generically without binding to
/// a trait. The macro expands the per-type scan at call site.
macro_rules! enumerate_rust {
    ($enum_ty:ty) => {{
        let mut out: BTreeMap<u32, String> = BTreeMap::new();
        // 0xEA60 (AdminEnvirons-class range) through 0xF7FF cover every
        // currently-defined opcode across all three Rust enums with margin.
        for v in 0u32..0xF800u32 {
            if let Some(variant) = <$enum_ty>::from_repr(v) {
                out.insert(v, format!("{variant:?}"));
            }
        }
        out
    }};
}

/// Categorization-gate allowlist: opcodes where retail
/// (acclient.c / ACE-Server) confirms Rust is correct and Chorizite is wrong
/// (or incomplete). Each entry pairs (enum_label, value) with an evidence
/// citation kept in-source so future audits can re-verify without re-research.
///
/// Format: (enum_label, opcode_value, reason_string).
const CATEGORIZATION_GATE_ALLOWLIST: &[(&str, u32, &str)] = &[
    // ----- GameOpcode -----
    (
        "GameOpcode",
        0x0000,
        "Internal/sentinel — None opcode is not a wire value. \
         Never present in Chorizite by design.",
    ),
    (
        "GameOpcode",
        0xF753,
        "AutonomousPosition is bidirectional in retail. C2S goes through \
         GameActionType.AutonomousPosition (acclient.c \
         CM_Movement::Event_AutonomousPosition @ 712832 writes 0xF753 inside \
         OrderHdr-wrapped GameAction); S2C goes through \
         GameMessageOpcode.AutonomousPosition (ACE-Server \
         GameMessageAutonomousPosition : GameMessage with \
         GameMessageOpcode.AutonomousPosition = 0xF753). Rust keeps BOTH \
         placements (one in GameOpcode for S2C, one in GameActionOpcode for \
         C2S). Chorizite only has the C2S side, so the Rust S2C copy reads as \
         a phantom 'in Rust but not in Chorizite' — that's Chorizite being \
         incomplete, not Rust being wrong.",
    ),
    // ----- GameActionOpcode -----
    (
        "GameActionOpcode",
        0x021A,
        "RemovePlayerPermission lives at 0x021A in retail, not 0x0220 as \
         Chorizite claims. Per acclient.c \
         CM_Character::Event_RemovePlayerPermission @ 699582, the wire opcode \
         written after OrderHdr is 538 (= 0x021A). The 0x0219 / 0x021A pair \
         (Add / Remove PlayerPermission) is contiguous; Chorizite's 0x0220 \
         conflicts with House_RemoveAllStoragePermission territory and looks \
         like a typo upstream.",
    ),
    // ----- GameEventOpcode -----
    (
        "GameEventOpcode",
        0x00A0,
        "InventoryServerSaveFailed is a GameEvent (inside 0xF7B0), not a \
         top-level S2C message. ACE-Server \
         GameEventInventoryServerSaveFailed : GameEventMessage(\
         GameEventType.InventoryServerSaveFailed = 0x00A0, \
         GameMessageGroup.UIQueue) confirms 0x00A0 is dispatched via the \
         GameEvent path. acclient.c UIQueueManager::ProcessNetBlobData \
         @ 394441 dispatches case 0xA0u alongside other GameEvent inner \
         opcodes (0x13 PlayerDescription, 0x52 CloseGroundContainer, …). \
         Chorizite categorizes it as top-level S2CMessageType.\
         Character_ServerSaysAttemptFailed, which is wrong.",
    ),
];

/// True if `(label, value)` is on the allowlist.
fn is_allowlisted(label: &str, value: u32) -> bool {
    CATEGORIZATION_GATE_ALLOWLIST
        .iter()
        .any(|(l, v, _)| *l == label && *v == value)
}

/// Render the allowlist as a human-readable diagnostic when the gate fails
/// and an opcode IS on the list — helps reviewers spot stale entries.
fn render_allowlist() -> String {
    let mut s = String::new();
    s.push_str("Currently-allowlisted Rust-not-in-Chorizite cases:\n");
    for (label, value, reason) in CATEGORIZATION_GATE_ALLOWLIST {
        s.push_str(&format!("  [{label}] 0x{value:04X} — {reason}\n"));
    }
    s
}

/// Build the unified GameOpcode-side view of Chorizite. C2SMessageType and
/// S2CMessageType are merged because Rust's `GameOpcode` covers both
/// directions (and some opcodes like 0xF7DE TurbineChat are bidirectional).
fn chor_game_unified(chor: &BTreeMap<String, OpcodeMap>) -> OpcodeMap {
    let mut out = OpcodeMap::new();
    for (v, name) in chor.get("C2SMessageType").expect("C2SMessageType missing") {
        out.insert(*v, format!("C2S:{name}"));
    }
    for (v, name) in chor.get("S2CMessageType").expect("S2CMessageType missing") {
        out.entry(*v)
            .and_modify(|existing| {
                *existing = format!("{existing}+S2C:{name}");
            })
            .or_insert_with(|| format!("S2C:{name}"));
    }
    out
}

/// Collect every diff line and print them ALL at the end. Don't short-circuit
/// on first failure — the audit's value is the full report.
struct DiffReport {
    enum_label: &'static str,
    missing_in_rust: Vec<(u32, String)>,
    missing_in_chor: Vec<(u32, String)>,
}

// `DiffReport` is rendered inline by each test rather than via shared helpers
// — the categorization gate cares about `missing_in_chor` only, and the
// aspirational test about `missing_in_rust` only.

fn diff(
    label: &'static str,
    chor: &OpcodeMap,
    rust: &BTreeMap<u32, String>,
) -> DiffReport {
    let mut missing_in_rust = Vec::new();
    let mut missing_in_chor = Vec::new();

    for (v, name) in chor {
        if !rust.contains_key(v) {
            missing_in_rust.push((*v, name.clone()));
        }
    }
    for (v, name) in rust {
        if !chor.contains_key(v) {
            missing_in_chor.push((*v, name.clone()));
        }
    }

    DiffReport {
        enum_label: label,
        missing_in_rust,
        missing_in_chor,
    }
}

/// Build the three diff reports against the current dump.
fn build_diffs() -> (DiffReport, DiffReport, DiffReport) {
    let chor = load_json();
    let chor_game = chor_game_unified(&chor);
    let chor_action = chor.get("GameActionType").expect("GameActionType missing");
    let chor_event = chor.get("GameEventType").expect("GameEventType missing");

    let rust_game = enumerate_rust!(GameOpcode);
    let rust_action = enumerate_rust!(GameActionOpcode);
    let rust_event = enumerate_rust!(GameEventOpcode);

    (
        diff("GameOpcode", &chor_game, &rust_game),
        diff("GameActionOpcode", chor_action, &rust_action),
        diff("GameEventOpcode", chor_event, &rust_event),
    )
}

/// CI gate: assert ZERO Rust-not-in-Chorizite categorization/value
/// mismatches outside the known-sentinel allowlist. Chorizite-not-in-Rust
/// gaps are intentional curation and are surfaced separately by
/// `opcode_parity_aspirational_stubs`.
#[test]
fn opcode_parity_categorization_gate() {
    let (report_game, report_action, report_event) = build_diffs();

    let mut unexplained: Vec<(&'static str, u32, String)> = Vec::new();
    for (v, name) in &report_game.missing_in_chor {
        if !is_allowlisted("GameOpcode", *v) {
            unexplained.push(("GameOpcode", *v, name.clone()));
        }
    }
    for (v, name) in &report_action.missing_in_chor {
        if !is_allowlisted("GameActionOpcode", *v) {
            unexplained.push(("GameActionOpcode", *v, name.clone()));
        }
    }
    for (v, name) in &report_event.missing_in_chor {
        if !is_allowlisted("GameEventOpcode", *v) {
            unexplained.push(("GameEventOpcode", *v, name.clone()));
        }
    }

    if unexplained.is_empty() {
        eprintln!(
            "opcode parity categorization gate PASS — {} allowlisted Rust-only cases acknowledged",
            CATEGORIZATION_GATE_ALLOWLIST.len()
        );
        return;
    }

    let mut msg = String::new();
    msg.push_str(&format!(
        "\nopcode parity categorization gate FAIL — {} unexplained Rust-only opcodes:\n",
        unexplained.len()
    ));
    for (label, value, name) in &unexplained {
        msg.push_str(&format!("  [{label}] 0x{value:04X} {name}\n"));
    }
    msg.push_str("\nEach line is an opcode where the Rust enum claims this opcode exists\n");
    msg.push_str("but Chorizite.ACProtocol does not — meaning either Rust has the wrong\n");
    msg.push_str("categorization/value, or retail confirms Rust is right and the entry\n");
    msg.push_str("belongs on CATEGORIZATION_GATE_ALLOWLIST with an acclient.c citation.\n\n");
    msg.push_str(&render_allowlist());

    panic!("{}", msg);
}

/// Aspirational audit: lists every opcode in Chorizite that is missing from
/// Rust. Currently the Rust enums are a curated subset of the retail
/// protocol — commented stubs in `opcodes.rs` document what's intentionally
/// not yet wired. Un-ignore this test once all S2C/GameEvent opcodes are
/// wired up and we want full parity. Run with `cargo test ... -- --ignored`.
#[test]
#[ignore = "aspirational: un-ignore once we wire all S2C/GameEvent opcodes; today these are aspirational stubs in opcodes.rs comments"]
fn opcode_parity_aspirational_stubs() {
    let (report_game, report_action, report_event) = build_diffs();

    let total_gaps = report_game.missing_in_rust.len()
        + report_action.missing_in_rust.len()
        + report_event.missing_in_rust.len();

    if total_gaps == 0 {
        eprintln!(
            "opcode parity aspirational stubs PASS — Rust covers every Chorizite opcode"
        );
        return;
    }

    let mut msg = String::new();
    msg.push_str(&format!(
        "\nopcode parity aspirational drift — {} Chorizite opcodes still missing from Rust:\n",
        total_gaps
    ));
    // Reuse the existing rendering, but only show the missing_in_rust half.
    for r in &[&report_game, &report_action, &report_event] {
        if !r.missing_in_rust.is_empty() {
            msg.push_str(&format!(
                "  [{}] {} opcodes in Chorizite.ACProtocol but NOT in Rust:\n",
                r.enum_label,
                r.missing_in_rust.len()
            ));
            for (v, name) in &r.missing_in_rust {
                msg.push_str(&format!("    0x{v:04X} {name}\n"));
            }
        }
    }
    msg.push_str("\nThese are intentional stubs in opcodes.rs comments — un-comment + wire up\n");
    msg.push_str("the corresponding message data structures + handlers, then this test will\n");
    msg.push_str("pass and can have its `#[ignore]` removed.\n");

    panic!("{}", msg);
}

/// Sanity-only test (NOT ignored) that asserts the JSON file is present and
/// parses cleanly. This catches "WB.Terminal regenerated the dump but
/// emitted malformed JSON" failure modes without requiring the full diff
/// audit to be un-ignored.
#[test]
fn opcode_parity_dump_is_well_formed() {
    let parsed = load_json();
    // The five expected enums.
    for name in &[
        "C2SMessageType",
        "S2CMessageType",
        "GameActionType",
        "GameEventType",
        "GameMessageGroup",
    ] {
        let block = parsed
            .get(*name)
            .unwrap_or_else(|| panic!("expected enum {name} missing from dump"));
        assert!(
            !block.is_empty(),
            "dumped enum {name} has zero members"
        );
    }
    // Spot-check a stable, well-known opcode.
    let actions = parsed.get("GameActionType").unwrap();
    let melee = actions
        .get(&0x0008)
        .expect("GameActionType is missing 0x0008 (TargetedMeleeAttack)");
    assert!(
        melee.contains("TargetedMeleeAttack"),
        "GameActionType 0x0008 should be TargetedMeleeAttack, got {melee:?}"
    );
}
